    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Uniform internal rows/columns of a non-background color are dividers.
    candidates = []
    for r in range(1, h - 1):
        if len(set(grid[r])) == 1 and grid[r][0] != background:
            candidates.append((grid[r][0], "row", r))
    for c in range(1, w - 1):
        if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background:
            candidates.append((grid[0][c], "col", c))

    if not candidates:
        return [row[:] for row in grid]

    divider_color = max(
        {color for color, _, _ in candidates},
        key=lambda color: sum(c == color for c, _, _ in candidates)
    )
    row_dividers = sorted(i for color, axis, i in candidates
                          if color == divider_color and axis == "row")
    col_dividers = sorted(i for color, axis, i in candidates
                          if color == divider_color and axis == "col")

    def blocks(length, dividers):
        result = []
        start = 0
        for d in dividers:
            result.append((start, d))
            start = d + 1
        result.append((start, length))
        return result

    row_blocks = blocks(h, row_dividers)
    col_blocks = blocks(w, col_dividers)

    tiles = []
    for r0, r1 in row_blocks:
        for c0, c1 in col_blocks:
            score = sum(grid[r][c] != background
                        for r in range(r0, r1)
                        for c in range(c0, c1))
            tiles.append((score, r0, r1, c0, c1))

    _, sr0, sr1, sc0, sc1 = max(tiles)
